-- Uldaman (map 70), 2026-11-13.
--
-- 1. The Stone Keepers, Archaedas and his minions could not be attacked once awake.
--    Their templates carry UNIT_FLAG_IMMUNE_TO_PC 0x100 + IMMUNE_TO_NPC 0x200 + NOT_SELECTABLE 0x2000000.
--    The scripts (npc_stonekeepers, boss_archaedas, npc_archaedas_minions, instance_uldaman) freeze
--    them themselves on reset (faction 35, NOT_SELECTABLE, rooted, stone aura) and only take
--    NOT_SELECTABLE and the faction away when they wake, so the immune flags stayed for good.
--    2748 Archaedas 33588032 -> 32832, 4857 Stone Keeper 33555264 -> 64,
--    7076 Earthen Guardian / 7077 Earthen Hallshaper / 7309 Earthen Custodian 33587968 -> 32768,
--    10120 Vault Warder 33555264 -> 64.
-- 2. Only Earthen Hallshaper 7077 had ScriptName npc_archaedas_minions. Earthen Custodian 7309,
--    Earthen Guardian 7076 and Vault Warder 10120 had none, so they never froze and never woke
--    with Archaedas (the Pandaria 5.4.8 database has the script on all four).
-- 3. The Keystone 124371 (guid 188122) was spawned already used (state 0). Clicking it opens the
--    Seal of Khaz'Mul and releases Ironaya; spawn it ready (state 1).
-- 4. Movement: all 293 spawns stood still. Patrols from the Pandaria 5.4.8 database (same guids)
--    and AzerothCore (matched by entry and nearest path point), paths 70000001+; wander radius from
--    AzerothCore (max 5 yards). Bosses, the Stone Keepers, Archaedas' room and the dig teams are left alone.
-- The dig teams, Ironaya and Archaedas' minion respawn are handled by tools/bfa/uldaman.patch.

-- 1. Immune flags
UPDATE `creature_template` SET `unit_flags` = `unit_flags` & ~33555200    -- 0x100 | 0x200 | 0x2000000
WHERE `entry` IN (2748, 4857, 7076, 7077, 7309, 10120);

-- 2. Archaedas' minions
UPDATE `creature_template` SET `ScriptName` = 'npc_archaedas_minions' WHERE `entry` IN (7076, 7077, 7309, 10120);

-- 3. Keystone
UPDATE `gameobject` SET `state` = 1 WHERE `guid` = 188122 AND `id` = 124371;

-- 4. Patrols
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 70000001 AND 70001000;
ON DUPLICATE KEY UPDATE `path_id`=VALUES(`path_id`);
UPDATE `creature` SET `MovementType`=2, `spawndist`=0 WHERE `guid` IN (320833, 320859, 320865, 320881, 320896, 320958, 320959, 320960, 320983, 320984, 320985, 320996);

-- Random wandering (AzerothCore wander radius)
UPDATE `creature` SET `MovementType`=1, `spawndist`=1 WHERE `MovementType`=0 AND `guid` IN (320790, 320791, 320792, 320796, 320798, 320848, 320849, 320850, 320851, 320853, 320939, 320942, 320943, 320944, 320945, 320946, 320947, 320948, 320950, 320952, 320953, 320955, 320956, 320957);
UPDATE `creature` SET `MovementType`=1, `spawndist`=2 WHERE `MovementType`=0 AND `guid` IN (320825, 320837, 320838, 320839, 320840, 320885, 320886, 320889, 320892, 320893, 320894, 320901, 320905, 320906, 320962, 320974, 321009);
UPDATE `creature` SET `MovementType`=1, `spawndist`=3 WHERE `MovementType`=0 AND `guid` IN (320820, 320824, 320912, 320927, 320964, 320972, 321012);
UPDATE `creature` SET `MovementType`=1, `spawndist`=5 WHERE `MovementType`=0 AND `guid` IN (320830, 320975, 320995);

-- Check
SELECT CONCAT((SELECT COUNT(*) FROM `creature` WHERE `map` = 70 AND `MovementType` = 2), ' patrols, ',
              (SELECT COUNT(*) FROM `creature` WHERE `map` = 70 AND `MovementType` = 1), ' wanderers, Archaedas unit_flags ',
              (SELECT `unit_flags` FROM `creature_template` WHERE `entry` = 2748)) AS `uldaman`;
